INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',1015,'{"_type":"chat:Message","id":"8641420749:175","threadId":"telegram:8641420749","text":"**Done today?** Setup Career-ops and get acquainted with it to start finding interesting companies.\n**Learned?** DS and FDE are more common roles than I thought, I found them both again at HappyRobots\n**Tomorrow''s first action?** Make sure to move away from job-post centric research to create company list and rather focus on companies core products, funding state, pure interest for me. So I can start being excited about companies I see. This will be the pulls I need \"Look at all these interesting companies I''ve found based in Madrid\"","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"strong","children":[{"type":"text","value":"Done today?","position":{"start":{"line":1,"column":3,"offset":2},"end":{"line":1,"column":14,"offset":13}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":16,"offset":15}}},{"type":"text","value":" Setup Career-ops and get acquainted with it to start finding interesting companies.\n","position":{"start":{"line":1,"column":16,"offset":15},"end":{"line":2,"column":1,"offset":100}}},{"type":"strong","children":[{"type":"text","value":"Learned?","position":{"start":{"line":2,"column":3,"offset":102},"end":{"line":2,"column":11,"offset":110}}}],"position":{"start":{"line":2,"column":1,"offset":100},"end":{"line":2,"column":13,"offset":112}}},{"type":"text","value":" DS and FDE are more common roles than I thought, I found them both again at HappyRobots\n","position":{"start":{"line":2,"column":13,"offset":112},"end":{"line":3,"column":1,"offset":201}}},{"type":"strong","children":[{"type":"text","value":"Tomorrow''s first action?","position":{"start":{"line":3,"column":3,"offset":203},"end":{"line":3,"column":27,"offset":227}}}],"position":{"start":{"line":3,"column":1,"offset":201},"end":{"line":3,"column":29,"offset":229