INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:-5124234082',959,'{"_type":"chat:Message","id":"-5124234082:4095","threadId":"telegram:-5124234082","text":"Poireau on les avait mis dans la soupe j’avais oublié. Branca ne vient pas cette semaine et la semaine prochaine. Hier on a diné des dumplings.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Poireau on les avait mis dans la soupe j’avais oublié. Branca ne vient pas cette semaine et la semaine prochaine. Hier on a diné des dumplings.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":144,"offset":143}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":144,"offset":143}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":144,"offset":143}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-10-26T09:17:46.000Z","edited":false},"attachments":[],"isMention":false}',1793611065133);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',1035,'{"_type":"chat:Message","id":"8641420749:2192","threadId":"telegram:8641420749","text":"J’ai clairement forcé hier, je sens que la cuisse gauche a souffert. J’ai une sensation de courbature assez intense mais surtout dans la cuisse gauche. Je pense que si j’avais continué ou poussé un peu plus fort ça aurait pu claquer/ me blesser. Pas de sensation dans les genoux ou dans la cheville par contre. \n\nIl faut que j’utilise les 2-3 jours qui viennent de maniere optimale pour recuperer. Nutrition/etirement/active recovery… fais moi le meilleur plan pour aujourd’hui et demain.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"J’ai clairement forcé hier, je sens que la cuisse gauche a souffert. J’ai une sensation de courbature assez intense mais surtout dans la cuisse gauche. Je pense que si j’avais continué ou poussé un peu plus fort ça aurait pu claquer/ me blesser. Pas de sensation dans les genoux ou dans la cheville par contre.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":311,"offset":310}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":312,"offset":311}}},{"type":"paragraph","children":[{"type":"text","value":"Il faut que j’utilise les 2-3 jours qui viennent de maniere optimale pour recuperer. Nutrition/etirement/active recovery… fais moi le meilleur plan pour aujourd’hui et demain.","position":{"start":{"line":3,"column":1,"offset":313},"end":{"line":3,"column":176,"offset":488}}}],"position":{"start":{"line":3,"column":1,"offset":313},"end":{"line":3,"column":176,"offset":488}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":3,"column":176,"offset":488}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-10-26T09:49:18.000Z","edited":false},"attachments":[],"isMention":false}',1793612959630);
