INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',1039,'{"_type":"chat:Message","id":"8641420749:195","threadId":"telegram:8641420749","text":"I just wrote to Luis Reis, ex colleague who I hired in my team some years ago, he now leaves in Madrid and work as Product Manager","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"I just wrote to Luis Reis, ex colleague who I hired in my team some years ago, he now leaves in Madrid and work as Product Manager","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":131,"offset":130}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":131,"offset":130}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":131,"offset":130}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-10-26T11:02:28.000Z","edited":false},"attachments":[],"isMention":false}',1793617347375);
