INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',1041,'{"_type":"chat:Message","id":"8641420749:2199","threadId":"telegram:8641420749","text":"/done","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"/done","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":6,"offset":5}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":6,"offset":5}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":6,"offset":5}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-10-26T18:26:34.000Z","edited":false},"attachments":[],"isMention":false}',1793643994749);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',1042,'{"_type":"chat:Message","id":"8641420749:202","threadId":"telegram:8641420749","text":"Today I''ve spent a good amount time creating the list of companies from Madrid using Perplexity, using the DeepSeek model, using Claude, and with different constraints and different industry focus. I''ve also tried to list all the big names in Madrid, whether big tech, very successful scale-ups, or even AI labs.\n\nLet''s say I''ve done the easy work and now I have to do the brain work of going through those companies, analyzing them, and learning about them. All this is stored in Career Ops. What I learned is that there are more big tech companies and AI lab companies than I thought. I also keep seeing forward deploy engineer and deployment strategist roles so it really seems to be a thing, even in Europe.\n\nThere seems to be remote work possible from Spain, from big companies like N8N or other Berlin-based companies. Let''s see. I''m starting to gather this list of companies. It''s interesting. They are all now added to the scan, meaning that when Career Ops scans for new job openings, it will also check those companies.\n\nTomorrow''s first action: I think it would be nice to do the LinkedIn Rehab from my current CV and optimize it for the 2 types of roles (ideal/backup). So that it gives me the feeling that I can confidently share it with people, including my JSC. Do you see a better next step?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Today I''ve spent a good amount time creating the list of companies from Madrid using Perplexity, using the DeepSeek model, using Claude, and with different constraints and different industry focus. I''ve also tried to list all the big names in Madrid, whether big tech, very successful scale-ups, or even AI labs.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":313,"offset":312}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":313,"offset":312}}},{"type":"paragraph","children":[{"type":"text","value":"Let''s say I''ve done the easy work and now I have to do the brain work of going through those companies, analyzing them, and learning about them. All this is stored in Career Ops. What I learned is that there are more big tech companies and AI lab companies than I thought. I also keep seeing forward deploy engineer and deployment strategist roles so it really seems to be a thing, even in Europe.","position":{"start":{"line":3,"column":1,"offset":314},"end":{"line":3,"column":398,"offset":711}}}],"position":{"start":{"line":3,"column":1,"offset":314},"end":{"line":3,"column":398,"offset":711}}},{"type":"paragraph","children":[{"type":"text","value":"There seems to be remote work possible from Spain, from big companies like N8N or other Berlin-based companies. Let''s see. I''m starting to gather this list of companies. It''s interesting. They are all now added to the scan, meaning that when Career Ops scans for new job openings, it will also check those companies.","position":{"start":{"line":5,"column":1,"offset":713},"end":{"line":5,"column":317,"offset":1029}}}],"position":{"start":{"line":5,"column":1,"offset":713},"end":{"line":5,"column":317,"offset":1029}}},{"type":"paragraph","children":[{"type":"text","value":"Tomorrow''s first action: I think it would be nice to do the LinkedIn Rehab from my current CV and optimize it for the 2 types of roles (ideal/backup). So that it gives me the feeling that I can confidently share it with people, including my JSC. Do you see a better next step?","position":{"start":{"line":7,"column":1,"offset":1031},"end":{"line":7,"column":277,"offset":1307}}}],"position":{"start":{"line":7,"column":1,"offset":1031},"end":{"line":7,"column":277,"offset":1307}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":7,"column":277,"offset":1307}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-10-26T18:31:20.000Z","edited":false},"attachments":[],"isMention":false}',1793644280613);
