INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',1056,'{"_type":"chat:Message","id":"8641420749:232","threadId":"telegram:8641420749","text":"I will have a call with Romain in 30min. He is also a Product Manager in search of a new job. He has pushed the AI topic quite far to support his job search. How would you approach the call? What would be the desired outcome?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"I will have a call with Romain in 30min. He is also a Product Manager in search of a new job. He has pushed the AI topic quite far to support his job search. How would you approach the call? What would be the desired outcome?","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":226,"offset":225}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":226,"offset":225}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":226,"offset":225}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-10-28T09:33:13.000Z","edited":false},"attachments":[],"isMention":false}',1793784793339);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',1057,'{"_type":"chat:Message","id":"8641420749:235","threadId":"telegram:8641420749","text":"**Summary: **\n• AI job search, what did you use, where do you stand, how can I help? Tell him about JSC\n• Je veux être proche de ce qui se passe en IA, ça m''attire, j''ai envie de remettre les mains dans le cambouis, mais c''est vrai que j''ai pas eu l''occasion de le faire dans mon dernier taff, ni de le mettre en place en tant que head of product. Ce que j''ai fait c''est des agents perso pour m''aider avec le taff de strategy.\n• Comment tu approcherais les choses pour : (1) me rendre attractif pour les recruteurs quand ils voient mon CV/LinkedIn (2) me chauffer pour les entretiens","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"**Summary: **\n• AI job search, what did you use, where do you stand, how can I help? Tell him about JSC\n• Je veux être proche de ce qui se passe en IA, ça m''attire, j''ai envie de remettre les mains dans le cambouis, mais c''est vrai que j''ai pas eu l''occasion de le faire dans mon dernier taff, ni de le mettre en place en tant que head of product. Ce que j''ai fait c''est des agents perso pour m''aider avec le taff de strategy.\n• Comment tu approcherais les choses pour : (1) me rendre attractif pour les recruteurs quand ils voient mon CV/LinkedIn (2) me chauffer pour les entretiens","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":4,"column":157,"offset":583}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":4,"column":157,"offset":583}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":4,"column":157,"offset":583}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-10-28T09:50:06.000Z","edited":false},"attachments":[],"isMention":false}',1793785806451);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',1058,'{"_type":"chat:Message","id":"8641420749:238","threadId":"telegram:8641420749","text":"Just had the call with Romain, some learnings: Pennylane hires remote in EU. I requested to join the FrenchProduit Community. His hands-on experience on personal project and personal Product Manager OS were enough for his interviews as PM with a strong emphasis on the AI aspect of the role. His second brain and the different apps he created were even higher than expected, so it''s reassuring for me since I built similar things for myself. His brother leaves in Sevilla, a contact for later. His own ai tool is very similar to the career-ops tool I use. No need to rebuild mine, I''ll just use this existing one. He is very nice and we agreed to stay in touch in the coming months.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Just had the call with Romain, some learnings: Pennylane hires remote in EU. I requested to join the FrenchProduit Community. His hands-on experience on personal project and personal Product Manager OS were enough for his interviews as PM with a strong emphasis on the AI aspect of the role. His second brain and the different apps he created were even higher than expected, so it''s reassuring for me since I built similar things for myself. His brother leaves in Sevilla, a contact for later. His own ai tool is very similar to the career-ops tool I use. No need to rebuild mine, I''ll just use this existing one. He is very nice and we agreed to stay in touch in the coming months.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":683,"offset":682}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":683,"offset":682}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":683,"offset":682}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-10-28T11:28:37.000Z","edited":false},"attachments":[],"isMention":false}',1793791716452);
