INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',1063,'{"_type":"chat:Message","id":"8641420749:253","threadId":"telegram:8641420749","text":"We can assume that I tested my ideal CMF with Romain this morning. My learnings is that having a pure AI PM role in an AI-native company might be a stretch but not impossible if I sell myself really well on all my personal AI projects. But I would have to really study and ramp up stronger on this aspect.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"We can assume that I tested my ideal CMF with Romain this morning. My learnings is that having a pure AI PM role in an AI-native company might be a stretch but not impossible if I sell myself really well on all my personal AI projects. But I would have to really study and ramp up stronger on this aspect.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":306,"offset":305}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":306,"offset":305}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":306,"offset":305}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-10-28T12:07:58.000Z","edited":false},"attachments":[],"isMention":false}',1793794077215);
