INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',1067,'{"_type":"chat:Message","id":"8641420749:265","threadId":"telegram:8641420749","text":"One of the key to do for this 1 Set up phase will be to write LinkedIn recommendation for some ex colleagues. This way I can then ask them to do the same.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"One of the key to do for this 1 Set up phase will be to write LinkedIn recommendation for some ex colleagues. This way I can then ask them to do the same.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":155,"offset":154}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":155,"offset":154}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":155,"offset":154}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-10-28T14:12:13.000Z","edited":false},"attachments":[],"isMention":false}',1793801532165);
