INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',1069,'{"_type":"chat:Message","id":"8641420749:268","threadId":"telegram:8641420749","text":"I will have a call with Luis Reis this afternoon. He is a PM I hired, he was in HR, I hired im as a PM trainee, coach him and grew him into a PM. Then he wanted to move to Madrid 3 years ago, I helped him with the move and connected him with some people. Now he is for sure better connected than me. What would be the best use of the time together?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"I will have a call with Luis Reis this afternoon. He is a PM I hired, he was in HR, I hired im as a PM trainee, coach him and grew him into a PM. Then he wanted to move to Madrid 3 years ago, I helped him with the move and connected him with some people. Now he is for sure better connected than me. What would be the best use of the time together?","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":349,"offset":348}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":349,"offset":348}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":349,"offset":348}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-10-28T15:05:58.000Z","edited":false},"attachments":[],"isMention":false}',1793804758094);
