INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',1071,'{"_type":"chat:Message","id":"8641420749:271","threadId":"telegram:8641420749","text":"Luis notes:\n• check Lenny''s meetup in Madrid it''s pretty big, led by Juan Serrano Miralles who is good friend of Luis and also good friend of Paco Crespo\n• other meetups are more entrepreneur-centric\n• AI meetups, he doesn''t know, i have to search for it\n• check https://symmetry.club/ startup\n• check bending spoons\n• check Barcelona based companies which accept Hybrid because they might accept once or twice on-site per month\n• check Ailin.health Head of Product job offer (asked for 70k and they were ok)\n• salary range Senior 55-65k for Madrid based spanish companies or international corporate, Group PM level 70k+\n• reach out to Paco Crespo, try to meet him in Madrid when going to Madrid. Keep Paco as a joker card, but not too late as he takes time to answer\n• Spanish managers tend to be more micro managers\n• reach out to José Ramón Pérez Agüera very well known and influential CTO/CPO in Madrid, Luis doesn''t know him personally\n• same for David Zafra\n• Luis knows David De Prado, he is more from Service Design and Design","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Luis notes:\n• check Lenny''s meetup in Madrid it''s pretty big, led by Juan Serrano Miralles who is good friend of Luis and also good friend of Paco Crespo\n• other meetups are more entrepreneur-centric\n• AI meetups, he doesn''t know, i have to search for it\n• check ","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":5,"column":9,"offset":263}}},{"type":"link","title":null,"url":"https://symmetry.club/","children":[{"type":"text","value":"https://symmetry.club/","position":{"start":{"line":5,"column":9,"offset":263},"end":{"line":5,"column":31,"offset":285}}}],"position":{"start":{"line":5,"column":9,"offset":263},"end":{"line":5,"column":31,"offset":285}}},{"type":"text","value":" startup\n• check bending spoons\n• check Barcelona based companies which accept Hybrid because they might accept once or twice on-site per month\n• check Ailin.health Head of Product job offer (asked for 70k and they were ok)\n• salary range Senior 55-65k for Madrid based spanish companies or international corporate, Group PM level 70k+\n• reach out to Paco Crespo, try to meet him in Madrid when going to Madrid. Keep Paco as a joker card, but not too late as he takes time to answer\n• Spanish managers tend to be more micro managers\n• reach out to José Ramón Pérez Agüera very well known and influential CTO/CPO in Madrid, Luis doesn''t know him personally\n• same for David Zafra\n• Luis knows David De Prado, he is more from Service Design and Design","position":{"start":{"line":5,"column":31,"offset":285},"end":{"line":14,"column":71,"offset":1034}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":14,"column":71,"offset":1034}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":14,"column":71,"offset":1034}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-10-28T17:35:03.000Z","edited":false},"attachments":[],"isMention":false}',1793813703214);
