INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',1100,'{"_type":"chat:Message","id":"8641420749:315","threadId":"telegram:8641420749","text":"Had a call with my friend Alexandra Darman. She''s an AI research engineer at Meta in San Francisco. One thing that she said is that she''s not coded a single line of code by herself for a year. She believes that job ads that require knowing how to code in Python or different things like this are just outdated. The reality at the edge is that you don''t code anymore. It''s really true: no hands-on coding exists anymore.\n\nIt''s pretty reassuring because I was a bit concerned with those forward-deployed engineer job descriptions that were requiring Python full proficiency and stuff like this. I think that those are things I can still target.\n\nAbout dawn today I did the Job Search Council but the reality is that it was not super motivating. The group is formed by two people who are the only two of the group of five people who have not found a job yet. Their energy is pretty low and they are both based in the UK. One is hard to understand because he has a stronger accent and I feel that they don''t have the energy I need. We agreed to meet one more time next week. I will do that just to help them but then I will tell them that I will not join anymore because I need stronger energy.\n\nFor the rest of the day I had to do things for the house and the family so I did not move anything else. I found one LinkedIn post from a head of product who is searching for someone interim, apparently from mid-February to September 2027. Those kinds of things could be an option. To keep an eye on it, probably still mark as a to-do to reach out to her.\n\nThat''s it. Did I miss anything? What should be tomorrow''s first action? I''m not sure. I need to check the to-dos. What do you think?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Had a call with my friend Alexandra Darman. She''s an AI research engineer at Meta in San Francisco. One thing that she said is that she''s not coded a single line of code by herself for a year. She believes that job ads that require knowing how to code in Python or different things like this are just outdated. The reality at the edge is that you don''t code anymore. It''s really true: no hands-on coding exists anymore.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":420,"offset":419}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":420,"offset":419}}},{"type":"paragraph","children":[{"type":"text","value":"It''s pretty reassuring because I was a bit concerned with those forward-deployed engineer job descriptions that were requiring Python full proficiency and stuff like this. I think that those are things I can still target.","position":{"start":{"line":3,"column":1,"offset":421},"end":{"line":3,"column":222,"offset":642}}}],"position":{"start":{"line":3,"column":1,"offset":421},"end":{"line":3,"column":222,"offset":642}}},{"type":"paragraph","children":[{"type":"text","value":"About dawn today I did the Job Search Council but the reality is that it was not super motivating. The group is formed by two people who are the only two of the group of five people who have not found a job yet. Their energy is pretty low and they are both based in the UK. One is hard to understand because he has a stronger accent and I feel that they don''t have the energy I need. We agreed to meet one more time next week. I will do that just to help them but then I will tell them that I will not join anymore because I need stronger energy.","position":{"start":{"line":5,"column":1,"offset":644},"end":{"line":5,"column":547,"offset":1190}}}],"position":{"start":{"line":5,"column":1,"offset":644},"end":{"line":5,"column":547,"offset":1190}}},{"type":"paragraph","children":[{"type":"text","value":"For the rest of the day I had to do things for the house and the family so I did not move anything else. I found one LinkedIn post from a head of product who is searching for someone interim, apparently from mid-February to September 2027. Those kinds of things could be an option. To keep an eye on it, probably still mark as a to-do to reach out to her.","position":{"start":{"line":7,"column":1,"offset":1192},"end":{"line":7,"column":356,"offset":1547}}}],"position":{"start":{"line":7,"column":1,"offset":1192},"end":{"line":7,"column":356,"offset":1547}}},{"type":"paragraph","children":[{"type":"text","value":"That''s it. Did I miss anything? What should be tomorrow''s first action? I''m not sure. I need to check the to-dos. What do you think?","position":{"start":{"line":9,"column":1,"offset":1549},"end":{"line":9,"column":133,"offset":1681}}}],"position":{"start":{"line":9,"column":1,"offset":1549},"end":{"line":9,"column":133,"offset":1681}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":9,"column":133,"offset":1681}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-10-29T17:42:52.000Z","edited":false},"attachments":[],"isMention":false}',1793900572578);
